CREATE TABLE wfc3d_document (id INTEGER PRIMARY KEY, schema_id TEXT NOT NULL, seed TEXT NOT NULL);
CREATE TABLE wfc3d_tile (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, label TEXT, weight REAL, media_kind TEXT NOT NULL CHECK(media_kind IN('mesh','mesh_child')), weight_bits INTEGER NOT NULL, weight_class TEXT NOT NULL);
CREATE TABLE wfc3d_mesh (id INTEGER PRIMARY KEY REFERENCES wfc3d_tile(id));
CREATE TABLE wfc3d_position (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES wfc3d_mesh(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), coordinate REAL, coordinate_bits INTEGER NOT NULL, coordinate_class TEXT NOT NULL);
CREATE TABLE wfc3d_index (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES wfc3d_mesh(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), vertex_index INTEGER NOT NULL CHECK(vertex_index BETWEEN 0 AND 4294967295));
CREATE TABLE wfc3d_color (id INTEGER PRIMARY KEY REFERENCES wfc3d_mesh(id), red INTEGER NOT NULL CHECK(red BETWEEN 0 AND 255), green INTEGER NOT NULL CHECK(green BETWEEN 0 AND 255), blue INTEGER NOT NULL CHECK(blue BETWEEN 0 AND 255), alpha INTEGER NOT NULL CHECK(alpha BETWEEN 0 AND 255));
CREATE TABLE wfc3d_mesh_child (id INTEGER PRIMARY KEY REFERENCES wfc3d_tile(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE wfc3d_slot (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, x REAL, y REAL, z REAL, width REAL, height REAL, depth REAL, pinned_tile_id TEXT, x_bits INTEGER NOT NULL, x_class TEXT NOT NULL, y_bits INTEGER NOT NULL, y_class TEXT NOT NULL, z_bits INTEGER NOT NULL, z_class TEXT NOT NULL, width_bits INTEGER NOT NULL, width_class TEXT NOT NULL, height_bits INTEGER NOT NULL, height_class TEXT NOT NULL, depth_bits INTEGER NOT NULL, depth_class TEXT NOT NULL);
CREATE TABLE wfc3d_slot_edge (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, from_slot_id TEXT NOT NULL, to_slot_id TEXT NOT NULL, relation TEXT NOT NULL);
CREATE TABLE wfc3d_rule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, tile_a_id TEXT NOT NULL, tile_b_id TEXT NOT NULL, relation TEXT, allowed INTEGER NOT NULL CHECK(allowed IN(0,1)));
